// MyApp/ContentView.swift
import SwiftUI

struct ContentView: View {
    @State private var message = "Replit Swift iOS App Loaded Successfully!"
    @State private var count = 0
    @State private var isLoading = false

    var body: some View {
        NavigationView {
            VStack(spacing: 25) {
                Text(message)
                    .font(.largeTitle)
                    .fontWeight(.bold)
                    .multilineTextAlignment(.center)
                    .padding(.horizontal)

                Text("Tap Counter: \(count)")
                    .font(.title2)
                    .fontWeight(.semibold)

                Button(action: {
                    count += 1
                    message = "Button tapped \(count) times from Replit-built native iOS app!"
                }) {
                    HStack {
                        Image(systemName: "hand.tap.fill")
                        Text("Tap Counter")
                    }
                    .font(.title2)
                    .padding()
                    .frame(maxWidth: .infinity)
                    .background(Color.blue)
                    .foregroundColor(.white)
                    .cornerRadius(12)
                }
                .disabled(isLoading)

                Button(action: {
                    Task {
                        isLoading = true
                        do {
                            let response = try await callReplitAPI()
                            message = response
                            count = 0
                        } catch {
                            message = "API Error: \(error.localizedDescription)"
                        }
                        isLoading = false
                    }
                }) {
                    HStack {
                        if isLoading {
                            ProgressView()
                                .scaleEffect(0.8)
                        } else {
                            Image(systemName: "network")
                        }
                        Text("Call Replit Backend API")
                    }
                    .font(.title3)
                    .padding()
                    .frame(maxWidth: .infinity)
                    .background(Color.green)
                    .foregroundColor(.white)
                    .cornerRadius(12)
                }
                .disabled(isLoading)

                Spacer()
            }
            .padding()
            .navigationTitle("Replit iOS Demo")
            .navigationBarTitleDisplayMode(.large)
        }
    }

    private func callReplitAPI() async throws -> String {
        guard let url = URL(string: "https://your-replit-name.your-repl.co/api/status") else {
            throw URLError(.badURL)
        }

        var request = URLRequest(url: url)
        request.httpMethod = "GET"
        request.setValue("application/json", forHTTPHeaderField: "Accept")

        let (data, response) = try await URLSession.shared.data(for: request)

        guard let httpResponse = response as? HTTPURLResponse,
              httpResponse.statusCode == 200 else {
            throw URLError(.badServerResponse)
        }

        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let status = json["status"] as? String,
              let message = json["message"] as? String else {
            throw URLError(.cannotParseResponse)
        }

        let responseMessage = "Replit API Response:\nStatus: \(status)\nMessage: \(message)\nTime: \(Date().formatted())"
        return responseMessage
    }
}

