# main.py
from flask import Flask, jsonify
from datetime import datetime
import os

app = Flask(__name__)

@app.route('/')
def home():
    return '''
    <h1>Replit iOS Backend API</h1>
    <p>Native Swift iOS app can call <code>/api/status</code></p>
    <p>Status: <span style="color:green">Ready</span></p>
    '''

@app.route('/api/status')
def status():
    return jsonify({
        'status': 'success',
        'message': 'Replit backend responding to native iOS Swift app',
        'timestamp': datetime.utcnow().isoformat() + 'Z',
        'version': '1.0.0',
        'platform': 'Replit Nix'
    })

@app.route('/api/health')
def health():
    return jsonify({
        'status': 'healthy',
        'uptime': '100%',
        'requests': 1
    })

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 8080))
    app.run(host='0.0.0.0', port=port, debug=False)


